function FaqPage({ settings }) {
  const [items, setItems] = useState(null);
  const [openId, setOpenId] = useState(null);
  const [error, setError] = useState(false);
  useEffect(() => { api.get("/faqs").then((response) => { setItems(response.data); setOpenId(response.data?.[0]?.id || null); }).catch(() => setError(true)); }, []);
  if (error) return <PublicLayout settings={settings}><EmptyPage title="Questions are unavailable" text="Please try again shortly." /></PublicLayout>;
  if (!items) return <PublicLayout settings={settings}><div className="loading-page" data-testid="faq-loading-state"><Loader2 className="spin" /> Loading questions</div></PublicLayout>;
  const visible = items.filter((item) => item.active !== false);
  const groups = visible.reduce((acc, item) => { const key = item.category || "General"; (acc[key] = acc[key] || []).push(item); return acc; }, {});
  return <PublicLayout settings={settings}><div className="listing-header page-width" data-testid="faq-page-header"><div className="eyebrow">Frequently asked</div><h1 data-testid="faq-page-heading">Things people ask us.</h1><p data-testid="faq-page-body">Practical answers to the questions we hear most. Missing yours? Send us a note.</p></div><section className="faq-list page-width" data-testid="faq-list-section">{Object.keys(groups).length ? Object.entries(groups).map(([category, list], groupIndex) => <div className="faq-group" key={category} data-testid={`faq-group-${groupIndex + 1}`}><div className="section-label" data-testid={`faq-group-label-${groupIndex + 1}`}>0{groupIndex + 1} / {category}</div><div className="faq-items">{list.map((item, index) => { const isOpen = openId === item.id; return <button type="button" className={`faq-item ${isOpen ? "is-open" : ""}`} key={item.id || item.title} onClick={() => setOpenId(isOpen ? null : item.id)} data-testid={`faq-item-${groupIndex + 1}-${index + 1}`}><span className="faq-question" data-testid={`faq-question-${groupIndex + 1}-${index + 1}`}><span>{item.title}</span><ChevronDown size={17} className={isOpen ? "faq-chevron open" : "faq-chevron"} /></span>{isOpen && <span className="faq-answer" data-testid={`faq-answer-${groupIndex + 1}-${index + 1}`}>{item.answer}</span>}</button>; })}</div></div>) : <div className="admin-empty full-span" data-testid="faq-empty-state">No questions posted yet. Ask us directly — we’ll be quick.</div>}</section></PublicLayout>;
}

function AdminLogin({ onLogin }) { const navigate = useNavigate(); const [email, setEmail] = useState("admin@studiovoxel.co"); const [password, setPassword] = useState("VoxelAdmin2026!"); const [error, setError] = useState(""); const [loading, setLoading] = useState(false); const submit = async (event) => { event.preventDefault(); setLoading(true); setError(""); try { const response = await api.post("/auth/login", { email, password }); localStorage.setItem("studio_voxel_token", response.data.access_token); onLogin(response.data.user); navigate("/admin/dashboard"); } catch (err) { setError(errorText(err)); } finally { setLoading(false); } }; return <main className="admin-login-page"><div className="admin-login-aside"><Link to="/" className="wordmark wordmark-light" data-testid="admin-login-logo-link"><span className="wordmark-mark">V</span><span>Studio Voxel</span></Link><div><div className="eyebrow">Private workspace</div><h1>Shape the work<br />behind the work.</h1><p>Manage the stories, images and details that make the studio visible.</p></div><span className="admin-aside-note">CMS / 01 — 2026</span></div><form className="admin-login-form" onSubmit={submit} data-testid="admin-login-form"><div className="eyebrow">Admin access</div><h2>Welcome back.</h2><p>Sign in to continue to your studio workspace.</p><Field label="Email address" name="email" type="email" value={email} onChange={setEmail} required testId="admin-email-input" /><Field label="Password" name="password" type="password" value={password} onChange={setPassword} required testId="admin-password-input" />{error && <div className="form-status error" data-testid="admin-login-error">{error}</div>}<button className="button button-dark full-button" disabled={loading} type="submit" data-testid="admin-login-submit-button">{loading ? <Loader2 className="spin" size={17} /> : "Enter workspace"}<ArrowUpRight size={16} /></button><Link to="/" className="back-link" data-testid="admin-login-back-link">← Return to website</Link></form></main>; }

function AdminGuard({ user, onLogin, children }) { if (!user) return <Navigate to="/admin/login" replace state={{ from: window.location.pathname }} />; return children; }

const adminNav = [["Overview", "/admin/dashboard", Grid2X2], ["Inbox", "/admin/inbox", Inbox], ["Services", "/admin/services", ChevronRight], ["Projects", "/admin/projects", ChevronRight], ["Gallery", "/admin/gallery", ChevronRight], ["Journal", "/admin/blog", ChevronRight], ["Testimonials", "/admin/testimonials", MessageSquareQuote], ["Team", "/admin/team", Users], ["FAQs", "/admin/faqs", ChevronRight], ["Media library", "/admin/media", ImagePlus], ["Settings", "/admin/settings", Settings]];
function AdminLayout({ user, onLogout, children }) { const location = useLocation(); const navigate = useNavigate(); const [unread, setUnread] = useState(0); const [toast, setToast] = useState(null); const previousUnread = useRef(null); useEffect(() => { const load = () => api.get("/dashboard").then((response) => { const next = response.data?.stats?.unread_contacts || 0; if (previousUnread.current !== null && next > previousUnread.current) { const delta = next - previousUnread.current; setToast({ id: Date.now(), text: `${delta} new ${delta === 1 ? "enquiry" : "enquiries"} arrived` }); } previousUnread.current = next; setUnread(next); }).catch(() => {}); load(); const timer = setInterval(load, 45000); return () => clearInterval(timer); }, [location.pathname]); useEffect(() => { if (!toast) return; const timer = setTimeout(() => setToast(null), 6000); return () => clearTimeout(timer); }, [toast]); const logout = async () => { await api.post("/auth/logout").catch(() => {}); localStorage.removeItem("studio_voxel_token"); onLogout(); navigate("/admin/login"); }; return <div className="admin-shell" data-testid="admin-shell"><aside className="admin-sidebar"><Link to="/admin/dashboard" className="wordmark" data-testid="admin-sidebar-logo-link"><span className="wordmark-mark">V</span><span>Studio Voxel</span></Link><div className="admin-nav-label">Workspace</div><nav className="admin-nav" data-testid="admin-sidebar-navigation">{adminNav.map(([label, href, Icon]) => <Link className={location.pathname === href ? "active" : ""} to={href} key={href} data-testid={`admin-${label.toLowerCase().replaceAll(" ", "-")}-nav-link`}><Icon size={16} /><span>{label}</span>{label === "Inbox" && unread > 0 && <span className="nav-badge" data-testid="admin-inbox-badge">{unread}</span>}</Link>)}</nav><div className="admin-user"><div className="avatar">SV</div><div><strong data-testid="admin-user-name">{user.name}</strong><span data-testid="admin-user-email">{user.email}</span></div><button onClick={logout} title="Sign out" data-testid="admin-logout-button"><LogOut size={16} /></button></div></aside><div className="admin-main"><header className="admin-topbar"><span className="admin-breadcrumb" data-testid="admin-breadcrumb-text">Studio / {adminNav.find((item) => item[1] === location.pathname)?.[0] || "Workspace"}</span><Link to="/" target="_blank" className="view-site-link" data-testid="admin-view-site-link">View website <ArrowUpRight size={15} /></Link></header>{children}</div>{toast && <button type="button" className="enquiry-toast" onClick={() => { setToast(null); navigate("/admin/inbox"); }} data-testid="admin-enquiry-toast"><Bell size={16} /><div><strong>{toast.text}</strong><span>Tap to open the inbox</span></div><X size={14} className="toast-close" /></button>}</div>; }

function AdminDashboard() { const [data, setData] = useState(null); useEffect(() => { api.get("/dashboard").then((response) => setData(response.data)); }, []); if (!data) return <AdminLoading />; const cards = [["projects", "Projects", "Live case studies"], ["services", "Services", "Visible offerings"], ["gallery", "Gallery", "Archive images"], ["blog", "Journal", "Published pieces"], ["testimonials", "Testimonials", "Client voices"], ["team", "Team", "Studio members"], ["faqs", "FAQs", "Answered questions"], ["media", "Media", "Uploaded assets"]]; return <AdminPage title="Good morning, studio." eyebrow="Overview" action={<Link to="/admin/projects" className="button button-dark" data-testid="dashboard-add-project-link"><Plus size={16} /> Add project</Link>}><div className="dashboard-intro"><p data-testid="dashboard-intro-text">Here’s what is happening across your website today.</p><span className="dashboard-date" data-testid="dashboard-date-text">{new Date().toLocaleDateString("en-GB", { weekday: "long", day: "numeric", month: "long" })}</span></div>{data.stats?.unread_contacts > 0 && <Link to="/admin/inbox" className="inbox-banner" data-testid="dashboard-inbox-banner"><Inbox size={18} /><div><strong>{data.stats.unread_contacts} unread {data.stats.unread_contacts === 1 ? "enquiry" : "enquiries"} in your inbox</strong><span>Open the inbox to reply or archive.</span></div><ArrowUpRight size={18} /></Link>}<div className="stat-grid">{cards.map(([key, label, caption]) => <div className="stat-card" key={key} data-testid={`dashboard-${key}-stat`}><span>{label}</span><strong>{data.stats[key] ?? 0}</strong><small>{caption}</small></div>)}</div><section className="admin-section"><div className="admin-section-heading"><div><span className="eyebrow">Latest activity</span><h2>Recent projects</h2></div><Link to="/admin/projects" className="text-link" data-testid="dashboard-projects-link">Manage projects <ArrowUpRight size={15} /></Link></div>{data.recent_projects.length ? <div className="recent-projects">{data.recent_projects.map((item, index) => <div className="recent-project" key={item.id} data-testid={`dashboard-recent-project-${index + 1}`}><ImageFrame src={item.image_url} alt={item.title} /><div><strong>{item.title}</strong><span>Published project</span></div><ChevronRight size={17} /></div>)}</div> : <div className="admin-empty" data-testid="dashboard-empty-state">No projects yet. Add your first case study to see it here.</div>}</section></AdminPage>; }

function AdminPage({ title, eyebrow, action, children }) { return <div className="admin-page" data-testid="admin-page"><div className="admin-page-heading"><div><div className="eyebrow">{eyebrow}</div><h1 data-testid="admin-page-title">{title}</h1></div>{action}</div>{children}</div>; }
function AdminLoading() { return <div className="admin-loading" data-testid="admin-loading-state"><Loader2 className="spin" /> Loading workspace</div>; }

function RichTextEditor({ value, onChange, testId }) {
  const ref = useRef(null);
  useEffect(() => {
    if (!ref.current) return;
    if (ref.current.innerHTML !== (value || "")) {
      ref.current.innerHTML = value || "";
    }
  }, []); // eslint-disable-line
  const exec = (command, arg = null) => {
    ref.current?.focus();
    document.execCommand(command, false, arg);
    onChange(ref.current?.innerHTML || "");
  };
  const wrap = (tag) => {
    ref.current?.focus();
    document.execCommand("formatBlock", false, tag);
    onChange(ref.current?.innerHTML || "");
  };
  const link = () => {
    const url = window.prompt("Link URL", "https://");
    if (!url) return;
    exec("createLink", url);
  };
  const clear = () => exec("removeFormat");
  const handleInput = () => onChange(ref.current?.innerHTML || "");
  const btn = (icon, label, action, tid) => <button type="button" onClick={action} className="rte-btn" title={label} aria-label={label} data-testid={tid}>{icon}</button>;
  return <div className="rte" data-testid={testId}>
    <div className="rte-toolbar" data-testid={`${testId}-toolbar`}>
      {btn(<Heading2 size={14} />, "Heading 2", () => wrap("H2"), `${testId}-h2`)}
      {btn(<Heading3 size={14} />, "Heading 3", () => wrap("H3"), `${testId}-h3`)}
      <span className="rte-sep" />
      {btn(<Bold size={14} />, "Bold", () => exec("bold"), `${testId}-bold`)}
      {btn(<Italic size={14} />, "Italic", () => exec("italic"), `${testId}-italic`)}
      <span className="rte-sep" />
      {btn(<Quote size={14} />, "Blockquote", () => wrap("BLOCKQUOTE"), `${testId}-quote`)}
      {btn(<List size={14} />, "Bullet list", () => exec("insertUnorderedList"), `${testId}-list`)}
      {btn(<LinkIcon size={14} />, "Link", link, `${testId}-link`)}
      <span className="rte-sep" />
      {btn(<X size={14} />, "Clear formatting", clear, `${testId}-clear`)}
    </div>
    <div className="rte-surface" contentEditable suppressContentEditableWarning ref={ref} onInput={handleInput} onBlur={handleInput} data-testid={`${testId}-surface`} />
  </div>;
}

function renderRichContent(content) {
  const text = content || "";
  if (/<\/?[a-z][\s\S]*>/i.test(text)) {
    return <div className="rte-rendered" dangerouslySetInnerHTML={{ __html: text }} />;
  }
  return <>{text.split(/\n\n+/).map((paragraph, index) => <p key={index}>{paragraph}</p>)}</>;
}

function MediaPicker({ onSelect, testId }) {
  const [open, setOpen] = useState(false);
  const [items, setItems] = useState(null);
  const [error, setError] = useState("");
  const load = () => { setError(""); setItems(null); api.get("/media").then((response) => setItems(Array.isArray(response.data) ? response.data : response.data?.items || [])).catch((err) => setError(errorText(err))); };
  useEffect(() => { if (open) load(); }, [open]);
  return <>
    <button type="button" className="picker-toggle" onClick={() => setOpen(true)} data-testid={testId || "media-picker-open"}><ImageIcon size={14} /> Choose from library</button>
    {open && <div className="admin-modal-backdrop picker-backdrop" onClick={() => setOpen(false)} data-testid="media-picker-modal">
      <div className="admin-modal picker-modal" onClick={(event) => event.stopPropagation()}>
        <div className="modal-heading"><div><span className="eyebrow">Media library</span><h2>Pick an image</h2></div><button type="button" onClick={() => setOpen(false)} data-testid="media-picker-close"><X /></button></div>
        {error && <div className="admin-notice">{error}</div>}
        {!items ? <AdminLoading /> : items.length ? <div className="picker-grid" data-testid="media-picker-grid">{items.map((item, index) => <button type="button" className="picker-card" key={item.id} onClick={() => { onSelect(`${BACKEND_URL}${item.url}`); setOpen(false); }} data-testid={`media-picker-item-${index + 1}`}><ImageFrame src={`${BACKEND_URL}${item.url}`} alt={item.original_name} /><span>{item.original_name}</span></button>)}</div> : <div className="admin-empty" data-testid="media-picker-empty">No uploads yet. Add images in Media library first.</div>}
      </div>
    </div>}
  </>;
}

const schemas = { services: { title: "Services", singular: "service", fields: [{ key: "title", label: "Title", required: true }, { key: "short_description", label: "Short description", required: true, type: "textarea" }, { key: "description", label: "Description", required: true, type: "textarea" }, { key: "image_url", label: "Image URL" }, { key: "icon", label: "Index" }, { key: "order", label: "Order", type: "number" }] }, projects: { title: "Projects", singular: "project", fields: [{ key: "title", label: "Title", required: true }, { key: "description", label: "Description", required: true, type: "textarea" }, { key: "image_url", label: "Main image URL" }, { key: "category", label: "Category" }, { key: "year", label: "Year" }, { key: "location", label: "Location" }, { key: "order", label: "Order", type: "number" }] }, gallery: { title: "Gallery", singular: "gallery item", fields: [{ key: "title", label: "Title", required: true }, { key: "description", label: "Description", type: "textarea" }, { key: "image_url", label: "Image URL", required: true }, { key: "category", label: "Category" }, { key: "alt_text", label: "Alt text", required: true }, { key: "order", label: "Order", type: "number" }] }, testimonials: { title: "Testimonials", singular: "testimonial", nameLabel: "Client", fields: [{ key: "title", label: "Client name", required: true }, { key: "role", label: "Role" }, { key: "company", label: "Company" }, { key: "quote", label: "Quote", required: true, type: "textarea" }, { key: "image_url", label: "Photo URL" }, { key: "rating", label: "Rating (1–5)", type: "number", min: 1, max: 5 }, { key: "featured", label: "Feature on homepage", type: "checkbox" }, { key: "order", label: "Order", type: "number" }] }, blog: { title: "Journal", singular: "post", nameLabel: "Post", fields: [{ key: "title", label: "Title", required: true }, { key: "excerpt", label: "Excerpt", required: true, type: "textarea" }, { key: "content", label: "Content", required: true, type: "richtext" }, { key: "image_url", label: "Cover image URL" }, { key: "author", label: "Author" }, { key: "tags", label: "Tags (comma separated)" }, { key: "published", label: "Published", type: "checkbox" }, { key: "order", label: "Order", type: "number" }] }, team: { title: "Team", singular: "team member", nameLabel: "Member", fields: [{ key: "title", label: "Full name", required: true }, { key: "role", label: "Role", required: true }, { key: "bio", label: "Short bio", type: "textarea" }, { key: "image_url", label: "Photo URL" }, { key: "instagram", label: "Instagram URL" }, { key: "linkedin", label: "LinkedIn URL" }, { key: "order", label: "Order", type: "number" }] }, faqs: { title: "FAQs", singular: "FAQ", nameLabel: "Question", fields: [{ key: "title", label: "Question", required: true, type: "textarea" }, { key: "answer", label: "Answer", required: true, type: "textarea" }, { key: "category", label: "Category" }, { key: "order", label: "Order", type: "number" }] } };
function AdminCrud({ collection }) { const schema = schemas[collection]; const [items, setItems] = useState([]); const [editing, setEditing] = useState(null); const [loading, setLoading] = useState(true); const [saving, setSaving] = useState(false); const [message, setMessage] = useState(""); const load = () => { setLoading(true); const url = collection === "blog" ? "/blog?include_drafts=true" : `/${collection}`; api.get(url).then((response) => setItems(response.data)).catch((error) => setMessage(errorText(error))).finally(() => setLoading(false)); }; useEffect(load, [collection]); const empty = Object.fromEntries(schema.fields.map((field) => [field.key, field.type === "number" ? 0 : field.type === "checkbox" ? false : ""])); const save = async (event) => { event.preventDefault(); setSaving(true); try { if (editing.id) await api.put(`/${collection}/${editing.id}`, editing); else await api.post(`/${collection}`, editing); setEditing(null); setMessage("Saved successfully"); load(); } catch (error) { setMessage(errorText(error)); } finally { setSaving(false); } }; const remove = async (item) => { if (!window.confirm(`Delete ${item.title}? This cannot be undone.`)) return; try { await api.delete(`/${collection}/${item.id}`); setMessage("Deleted successfully"); load(); } catch (error) { setMessage(errorText(error)); } }; const summaryOf = (item) => item.role || item.category || item.short_description || item.excerpt || (item.answer ? item.answer.slice(0, 80) : "") || "Content item"; return <AdminPage eyebrow="Website content" title={schema.title} action={<button className="button button-dark" onClick={() => setEditing(empty)} data-testid={`admin-add-${collection}-button`}><Plus size={16} /> Add {schema.singular}</button>}>{message && <div className="admin-notice" data-testid={`admin-${collection}-notice`}>{message}<button onClick={() => setMessage("")} data-testid={`admin-${collection}-notice-close`}><X size={14} /></button></div>}{loading ? <AdminLoading /> : <div className="admin-table-wrap" data-testid={`admin-${collection}-table`}><div className="admin-table-head"><span>{schema.nameLabel || "Name"}</span><span>Details</span><span>Status</span><span>Actions</span></div>{items.length ? items.map((item, index) => <div className="admin-table-row" key={item.id} data-testid={`admin-${collection}-row-${index + 1}`}><div className="table-title">{item.image_url && <ImageFrame src={item.image_url} alt={item.title} />}<strong>{item.title}</strong></div><span>{summaryOf(item)}</span><span className="status-dot"><i className={item.active === false || item.published === false ? "off" : ""} /> {item.active === false ? "Hidden" : item.published === false ? "Draft" : "Live"}</span><div className="row-actions"><button onClick={() => setEditing(item)} title="Edit" data-testid={`admin-${collection}-edit-${index + 1}`}><Pencil size={15} /></button><button onClick={() => remove(item)} title="Delete" data-testid={`admin-${collection}-delete-${index + 1}`}><Trash2 size={15} /></button></div></div>) : <div className="admin-empty" data-testid={`admin-${collection}-empty-state`}>No {schema.title.toLowerCase()} yet. Add your first one.</div>}</div>}{editing && <div className="admin-modal-backdrop" data-testid={`admin-${collection}-modal`}><form className="admin-modal" onSubmit={save}><div className="modal-heading"><div><span className="eyebrow">{editing.id ? "Edit" : "New"} {schema.singular}</span><h2>{editing.id ? editing.title : `Add ${schema.singular}`}</h2></div><button type="button" onClick={() => setEditing(null)} data-testid={`admin-${collection}-modal-close`}><X /></button></div><div className="modal-fields">{schema.fields.map((field) => { const isTextarea = field.type === "textarea"; const isRichText = field.type === "richtext"; const isCheckbox = field.type === "checkbox"; const isImageUrl = field.key === "image_url"; const spanClass = isTextarea || isRichText || isCheckbox || isImageUrl ? "form-field span-2" : "form-field"; if (isCheckbox) { return <label className={`${spanClass} checkbox-field`} key={field.key}><input type="checkbox" checked={!!editing[field.key]} onChange={(event) => setEditing({ ...editing, [field.key]: event.target.checked })} data-testid={`admin-${collection}-${field.key}-input`} /><span>{field.label}</span></label>; } if (isRichText) { return <div className={spanClass} key={field.key}><span className="form-field-label">{field.label}</span><RichTextEditor value={editing[field.key] || ""} onChange={(html) => setEditing({ ...editing, [field.key]: html })} testId={`admin-${collection}-${field.key}-editor`} /></div>; } return <label className={spanClass} key={field.key}><span className="field-label-row">{field.label}{isImageUrl && <MediaPicker onSelect={(url) => setEditing({ ...editing, [field.key]: url })} testId={`admin-${collection}-${field.key}-picker`} />}</span>{isTextarea ? <textarea required={field.required} value={editing[field.key] || ""} onChange={(event) => setEditing({ ...editing, [field.key]: event.target.value })} data-testid={`admin-${collection}-${field.key}-input`} /> : <input type={field.type || "text"} min={field.min} max={field.max} required={field.required} value={editing[field.key] ?? ""} onChange={(event) => setEditing({ ...editing, [field.key]: field.type === "number" ? Number(event.target.value) : event.target.value })} data-testid={`admin-${collection}-${field.key}-input`} />}{isImageUrl && editing[field.key] && <img className="field-image-preview" src={editing[field.key]} alt="preview" />}</label>; })}</div><div className="modal-actions"><button type="button" className="button button-quiet" onClick={() => setEditing(null)} data-testid={`admin-${collection}-cancel-button`}>Cancel</button><button className="button button-dark" disabled={saving} type="submit" data-testid={`admin-${collection}-save-button`}>{saving ? <Loader2 className="spin" size={16} /> : <Check size={16} />} Save changes</button></div></form></div>}</AdminPage>; }

function AdminMedia() { const [items, setItems] = useState([]); const [uploading, setUploading] = useState(false); const [loading, setLoading] = useState(true); const [message, setMessage] = useState(""); const load = () => { setLoading(true); api.get("/media").then((response) => setItems(Array.isArray(response.data) ? response.data : response.data?.items || [])).catch((error) => setMessage(errorText(error))).finally(() => setLoading(false)); }; useEffect(() => { load(); }, []); const upload = async (event) => { const files = Array.from(event.target.files || []); if (!files.length) return; const form = new FormData(); files.forEach((file) => form.append("files", file)); setUploading(true); try { await api.post("/media/upload", form); setMessage(`${files.length} image${files.length > 1 ? "s" : ""} uploaded`); load(); } catch (error) { setMessage(errorText(error)); } finally { setUploading(false); event.target.value = ""; } }; const remove = async (item) => { if (!window.confirm(`Delete ${item.original_name}?`)) return; try { await api.delete(`/media/${item.id}`); setMessage("Image deleted"); load(); } catch (error) { setMessage(errorText(error)); } }; return <AdminPage eyebrow="Assets" title="Media library" action={<label className="button button-dark upload-label" data-testid="admin-media-upload-button"><UploadCloud size={16} /> {uploading ? "Uploading…" : "Upload images"}<input type="file" accept="image/jpeg,image/png,image/webp" multiple hidden onChange={upload} data-testid="admin-media-file-input" /></label>}>{message && <div className="admin-notice" data-testid="admin-media-notice">{message}</div>}{loading ? <AdminLoading /> : <div className="media-grid" data-testid="admin-media-grid">{items.length ? items.map((item, index) => <div className="media-card" key={item.id} data-testid={`admin-media-card-${index + 1}`}><ImageFrame src={`${BACKEND_URL}${item.url}`} alt={item.original_name} /><div><strong>{item.original_name}</strong><span>{Math.round(item.size / 1024)} KB</span><button onClick={() => remove(item)} title="Delete image" data-testid={`admin-media-delete-${index + 1}`}><Trash2 size={15} /></button></div></div>) : <div className="admin-empty full-span" data-testid="admin-media-empty-state">Your media library is empty. Upload the first image to use it across the site.</div>}</div>}</AdminPage>; }

function AdminSettings() { const [settings, setSettings] = useState(null); const [saving, setSaving] = useState(false); const [message, setMessage] = useState(""); useEffect(() => { api.get("/settings").then((response) => setSettings(response.data)); }, []); if (!settings) return <AdminLoading />; const save = async (event) => { event.preventDefault(); setSaving(true); try { await api.put("/settings", settings); setMessage("Business information saved"); } catch (error) { setMessage(errorText(error)); } finally { setSaving(false); } }; return <AdminPage eyebrow="Configuration" title="Business settings"><form className="settings-form" onSubmit={save} data-testid="admin-settings-form"><div className="settings-grid">{Object.entries(settings).filter(([key]) => !["id", "updated_at"].includes(key)).map(([key, value]) => <label className="form-field" key={key}><span>{key.replaceAll("_", " ")}</span>{key === "footer_note" || key === "tagline" ? <textarea value={value || ""} onChange={(event) => setSettings({ ...settings, [key]: event.target.value })} data-testid={`admin-settings-${key}-input`} /> : <input value={value || ""} onChange={(event) => setSettings({ ...settings, [key]: event.target.value })} data-testid={`admin-settings-${key}-input`} />}</label>)}</div><div className="settings-actions"><button className="button button-dark" type="submit" disabled={saving} data-testid="admin-settings-save-button">{saving ? <Loader2 className="spin" size={16} /> : <Check size={16} />} Save settings</button>{message && <span className="form-status success" data-testid="admin-settings-status">{message}</span>}</div></form></AdminPage>; }

function AdminInbox() {
  const [items, setItems] = useState(null);
  const [active, setActive] = useState(null);
  const [message, setMessage] = useState("");
  const [filter, setFilter] = useState("all");
  const load = () => api.get("/contact-submissions").then((response) => setItems(response.data)).catch((error) => setMessage(errorText(error)));
  useEffect(() => { load(); }, []);
  const setStatus = async (item, status) => { try { await api.put(`/contact-submissions/${item.id}`, { status }); setMessage(status === "read" ? "Marked as read" : status === "archived" ? "Archived" : "Marked as new"); load(); if (active?.id === item.id) setActive({ ...item, status }); } catch (error) { setMessage(errorText(error)); } };
  const remove = async (item) => { if (!window.confirm(`Delete this enquiry from ${item.name}? This cannot be undone.`)) return; try { await api.delete(`/contact-submissions/${item.id}`); setMessage("Enquiry deleted"); if (active?.id === item.id) setActive(null); load(); } catch (error) { setMessage(errorText(error)); } };
  const openItem = (item) => { setActive(item); if (item.status === "new") setStatus(item, "read"); };
  if (!items) return <AdminLoading />;
  const filtered = items.filter((item) => filter === "all" ? true : filter === "unread" ? item.status === "new" : item.status === filter);
  const unread = items.filter((item) => item.status === "new").length;
  return <AdminPage eyebrow="Enquiries" title="Inbox">{message && <div className="admin-notice" data-testid="admin-inbox-notice">{message}<button onClick={() => setMessage("")}><X size={14} /></button></div>}<div className="filter-chips inbox-chips" data-testid="admin-inbox-filters">{[["all", `All (${items.length})`], ["unread", `Unread (${unread})`], ["read", "Read"], ["archived", "Archived"]].map(([key, label]) => <button key={key} type="button" className={filter === key ? "chip active" : "chip"} onClick={() => setFilter(key)} data-testid={`admin-inbox-filter-${key}`}>{label}</button>)}</div><div className="inbox-shell" data-testid="admin-inbox-shell"><ul className="inbox-list" data-testid="admin-inbox-list">{filtered.length ? filtered.map((item, index) => <li key={item.id} className={`inbox-item ${item.status === "new" ? "is-unread" : ""} ${active?.id === item.id ? "is-active" : ""}`} data-testid={`admin-inbox-row-${index + 1}`}><button type="button" onClick={() => openItem(item)} className="inbox-open" data-testid={`admin-inbox-open-${index + 1}`}><div className="inbox-row-top"><strong>{item.name}</strong><span className="inbox-date">{new Date(item.created_at).toLocaleDateString("en-GB", { day: "numeric", month: "short" })}</span></div><span className="inbox-project">{item.project_type}</span><p>{item.message}</p></button></li>) : <li className="admin-empty" data-testid="admin-inbox-empty-state">No enquiries in this view.</li>}</ul><aside className="inbox-detail" data-testid="admin-inbox-detail">{active ? <><div className="inbox-detail-head"><div><span className="eyebrow" data-testid="admin-inbox-detail-status">{active.status || "new"}</span><h2 data-testid="admin-inbox-detail-name">{active.name}</h2><p className="inbox-detail-meta" data-testid="admin-inbox-detail-meta">{active.project_type} · {new Date(active.created_at).toLocaleString("en-GB", { dateStyle: "medium", timeStyle: "short" })}</p></div><button type="button" onClick={() => setActive(null)} className="inbox-close" data-testid="admin-inbox-detail-close"><X size={16} /></button></div><div className="inbox-detail-contact"><a href={`mailto:${active.email}`} data-testid="admin-inbox-detail-email"><Mail size={14} /> {active.email}</a></div><p className="inbox-detail-body" data-testid="admin-inbox-detail-message">{active.message}</p><div className="inbox-detail-actions"><a href={`mailto:${active.email}?subject=Re:%20${encodeURIComponent(active.project_type)}`} className="button button-dark" data-testid="admin-inbox-reply-link"><Send size={15} /> Reply by email</a>{active.status !== "new" ? <button type="button" className="button button-quiet" onClick={() => setStatus(active, "new")} data-testid="admin-inbox-mark-unread"><Inbox size={15} /> Mark as unread</button> : <button type="button" className="button button-quiet" onClick={() => setStatus(active, "read")} data-testid="admin-inbox-mark-read"><Check size={15} /> Mark as read</button>}{active.status !== "archived" && <button type="button" className="button button-quiet" onClick={() => setStatus(active, "archived")} data-testid="admin-inbox-archive"><Archive size={15} /> Archive</button>}<button type="button" className="button button-quiet button-danger" onClick={() => remove(active)} data-testid="admin-inbox-delete"><Trash2 size={15} /> Delete</button></div></> : <div className="admin-empty" data-testid="admin-inbox-empty-detail">Select an enquiry to read the full message.</div>}</aside></div></AdminPage>;
}

function AdminApp({ user, setUser }) { return <AdminGuard user={user} onLogin={setUser}><AdminLayout user={user} onLogout={() => setUser(null)}><Routes><Route path="dashboard" element={<AdminDashboard />} /><Route path="inbox" element={<AdminInbox />} /><Route path="services" element={<AdminCrud collection="services" />} /><Route path="projects" element={<AdminCrud collection="projects" />} /><Route path="gallery" element={<AdminCrud collection="gallery" />} /><Route path="blog" element={<AdminCrud collection="blog" />} /><Route path="testimonials" element={<AdminCrud collection="testimonials" />} /><Route path="team" element={<AdminCrud collection="team" />} /><Route path="faqs" element={<AdminCrud collection="faqs" />} /><Route path="media" element={<AdminMedia />} /><Route path="settings" element={<AdminSettings />} /><Route path="*" element={<Navigate to="dashboard" replace />} /></Routes></AdminLayout></AdminGuard>; }

function App() { const [user, setUser] = useState(null); const [checking, setChecking] = useState(true); const { data } = useSiteData(); useEffect(() => { if (localStorage.getItem("studio_voxel_token")) api.get("/auth/me").then((response) => setUser(response.data)).catch(() => localStorage.removeItem("studio_voxel_token")).finally(() => setChecking(false)); else setChecking(false); }, []); if (checking) return <div className="app-loading" data-testid="app-loading-state"><span className="wordmark"><span className="wordmark-mark">V</span> Studio Voxel</span><Loader2 className="spin" /></div>; return <BrowserRouter><Routes><Route path="/" element={<HomePage data={data} />} /><Route path="/about" element={<AboutPage data={data} />} /><Route path="/services" element={<ServicesPage data={data} />} /><Route path="/projects" element={<ProjectsPage data={data} />} /><Route path="/projects/:slug" element={<ProjectDetailPage settings={data.settings} />} /><Route path="/gallery" element={<GalleryPage data={data} />} /><Route path="/blog" element={<BlogPage settings={data.settings} />} /><Route path="/blog/:slug" element={<BlogDetailPage settings={data.settings} />} /><Route path="/faq" element={<FaqPage settings={data.settings} />} /><Route path="/contact" element={<ContactPage settings={data.settings} />} /><Route path="/admin/login" element={<AdminLogin onLogin={setUser} />} /><Route path="/admin/*" element={<AdminApp user={user} setUser={setUser} />} /><Route path="*" element={<PublicLayout settings={data.settings}><EmptyPage title="Page not found" text="The page you’re looking for doesn’t exist." /></PublicLayout>} /></Routes></BrowserRouter>; }

export default App;